import{_ as p,a0 as o,w as d,s as r,ao as i,I as l,x as a,a1 as t,A as n}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"如何使用 CGI 腳本生成網頁 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 CGI 腳本生成網頁 | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 CGI 腳本生成網頁 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 CGI 腳本生成網頁 | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20171219 How to generate webpages using CGI scripts","title":"如何使用 CGI 腳本生成網頁","tag":"201804","desc":""},"relativePath":"201804/20171219 How to generate webpages using CGI scripts.md","filePath":"[post].md"}'),h={name:"201804/20171219 How to generate webpages using CGI scripts.md"};function g(c,s,u,b,k,C){const e=o("Link");return d(),r("div",null,[s[17]||(s[17]=i(`<h1 id="如何使用-cgi-腳本生成網頁" tabindex="-1">如何使用 CGI 腳本生成網頁 <a class="header-anchor" href="#如何使用-cgi-腳本生成網頁" aria-label="Permalink to “如何使用 CGI 腳本生成網頁”">​</a></h1><blockquote><p>通用網關接口（CGI）提供了使用任何語言生成動態網站的簡易方法。</p></blockquote><p>回到互聯網的開端，當我第一次創建了我的第一個商業網站，生活是如此的美好。</p><p>我安裝 Apache 並寫了一些簡單的 HTML 網頁，網頁上列出了一些關於我的業務的重要信息，比如產品概覽以及如何聯繫我。這是一個靜態網站，因為內容很少改變。由於網站的內容很少發生改變這一性質，因此維護起來也很簡單。</p><h3 id="靜態內容" tabindex="-1">靜態內容 <a class="header-anchor" href="#靜態內容" aria-label="Permalink to “靜態內容”">​</a></h3><p>靜態內容很簡單，同時也很常見。讓我們快速的瀏覽一些靜態網頁的例子。你不需要一個可運行網站來執行這些小實驗，只需要把這些文件放到家目錄，然後使用瀏覽器打開。你所看到的內容將和通過 Web 服務器提供這一文件看到的內容一樣。</p><p>對於一個靜態網站，你需要的第一件東西就是 <code>index.html</code> 文件，該文件通常放置在 <code>/var/www/html</code> 目錄下。這個文件的內容可以非常簡單，比如可以是像 “Hello, world” 這樣一句短文本，沒有任何 HTML 標記。它將簡單的展示文本串內容。在你的家目錄創建 <code>index.html</code> 文件，並添加 “hello, world” 作為內容（不需要引號）。在瀏覽器中通過下面的鏈接來打開這一文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>file:///home/&lt;你的家目錄&gt;/index.html</span></span></code></pre></div><p>所以 HTML 不是必須的，但是，如果你有大量需要格式化的文本，那麼，不用 HTML 編碼的網頁的結果將會令人難以理解。</p><p>所以，下一步就是通過使用一些 HTML 編碼來提供格式化，從而使內容更加可讀。下面這一命令創建了一個具有 HTML 靜態網頁所需要的絕對最小標記的頁面。你也可以使用你最喜歡的編輯器來創建這一內容。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>echo &quot;&lt;h1&gt;Hello World&lt;/h1&gt;&quot; &gt; test1.html</span></span></code></pre></div><p>現在，再次查看 <code>index.html</code> 文件，將會看到和剛才有些不同。</p><p>當然，你可以在實際的內容行上添加大量的 HTML 標記，以形成更加完整和標準的網頁。下面展示的是更加完整的版本，儘管在瀏覽器中會看到同樣的內容，但這也為更加標準化的網站奠定了基礎。繼續在 <code>index.html</code> 中寫入這些內容並通過瀏覽器查看。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>&lt;!DOCTYPE HTML PUBLIC &quot;-//w3c//DD HTML 4.0//EN&quot;&gt;</span></span>
<span class="line"><span>&lt;html&gt;</span></span>
<span class="line"><span>&lt;head&gt;</span></span>
<span class="line"><span>&lt;title&gt;My Web Page&lt;/title&gt;</span></span>
<span class="line"><span>&lt;/head&gt;</span></span>
<span class="line"><span>&lt;body&gt;</span></span>
<span class="line"><span>&lt;h1&gt;Hello World&lt;/h1&gt;</span></span>
<span class="line"><span>&lt;/body&gt;</span></span>
<span class="line"><span>&lt;/html&gt;</span></span></code></pre></div><p>我使用這些技術搭建了一些靜態網站，但我的生活正在改變。</p><h3 id="動態網頁" tabindex="-1">動態網頁 <a class="header-anchor" href="#動態網頁" aria-label="Permalink to “動態網頁”">​</a></h3>`,16)),l("p",null,[s[2]||(s[2]=a("我找了一份新工作，這份工作的主要任務就是創建並維護用於一個動態網站的 CGI（",-1)),l("ruby",null,[t(e,{href:"https://en.wikipedia.org/wiki/Common_Gateway_Interface"},{default:n(()=>[...s[0]||(s[0]=[a("公共網關接口",-1)])]),_:1}),s[1]||(s[1]=l("rt",null,"Common Gateway InterfaceM",-1))]),s[3]||(s[3]=a("）代碼。字面意思來看，動態意味着在瀏覽器中生成的網頁所需要的 HTML 是由每次訪問頁面時不同的數據所生成的。這些數據包括網頁表單中的用户輸入，以用來在資料庫中進行數據查找，結果數據被一些恰當的 HTML 包圍着並展示在所請求的瀏覽器中。但是這不需要非常複雜。",-1))]),s[18]||(s[18]=i(`<p>通過使用 CGI 腳本，你可以創建一些簡單或複雜的交互式程序，通過運行這些程序能夠生成基於輸入、計算、服務器的當前條件等改變的動態頁面。有許多種語言可以用來寫 CGI 腳本，在這篇文章中，我將談到的是 Perl 和 Bash ，其他非常受歡迎的 CGI 語言包括 PHP 和 Python 。</p><p>這篇文章不會介紹 Apache 或其他任何 web 服務器的安裝和配置。如果你能夠訪問一個你可以進行實驗的 Web 服務器，那麼你可以直接查看它們在瀏覽器中出現的結果。否則，你可以在命令列中運行程序來查看它們所創建的 HTML 文本。你也可以重定向 HTML 輸出到一個文件中，然後通過瀏覽器查看結果文件。</p><h3 id="使用-perl" tabindex="-1">使用 Perl <a class="header-anchor" href="#使用-perl" aria-label="Permalink to “使用 Perl”">​</a></h3><p>Perl 是一門非常受歡迎的 CGI 腳本語言，它的優勢是強大的文本操作能力。</p><p>為了使 CGI 腳本可執行，你需要在你的網站的 <code>httpd.conf</code> 中添加下面這行內容。這會告訴服務器可執行 CGI 文件的位置。在這次實驗中，不必擔心這個問題。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ScriptAlias /cgi-bin/ &quot;/var/www/cgi-bin/&quot;</span></span></code></pre></div><p>把下面的 Perl 代碼添加到文件 <code>index.cgi</code>，在這次實驗中，這個文件應該放在你的家目錄下。如果你使用 Web 服務器，那麼應把文件的所有者更改為 <code>apache.apache</code>，同時將文件權限設置為 755，因為無論位於哪，它必須是可執行的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/usr/bin/perl</span></span>
<span class="line"><span>print &quot;Content-type: text/html\\n\\n&quot;;</span></span>
<span class="line"><span>print &quot;&lt;html&gt;&lt;body&gt;\\n&quot;;</span></span>
<span class="line"><span>print &quot;&lt;h1&gt;Hello World&lt;/h1&gt;\\n&quot;;</span></span>
<span class="line"><span>print &quot;Using Perl&lt;p&gt;\\n&quot;;</span></span>
<span class="line"><span>print &quot;&lt;/body&gt;&lt;/html&gt;\\n&quot;;</span></span></code></pre></div><p>在命令列中運行這個程序並查看結果，它將會展示出它所生成的 HTML 內容</p><p>現在，在瀏覽器中查看 <code>index.cgi</code> 文件，你所看到的只是文件的內容。瀏覽器需要將它看做 CGI 內容，但是，Apache 不知道需要將這個文件作為 CGI 程序運行，除非 Apache 的配置中包括上面所展示的 <code>ScriptAlias</code> 定義。沒有這一配置，Apache 只會簡單地將文件中的數據發送給瀏覽器。如果你能夠訪問 Web 服務器，那麼你可以將可執行文件放到 <code>/var/www/cgi-bin</code> 目錄下。</p><p>如果想知道這個腳本的運行結果在瀏覽器中長什麼樣，那麼，重新運行程序並把輸出重定向到一個新文件，名字可以是任何你想要的。然後使用瀏覽器來查看這一文件，它包含了腳本所生成的內容。</p><p>上面這個 CGI 程序依舊生成靜態內容，因為它總是生成相同的輸出。把下面這行內容添加到 CGI 程序中 “Hello, world” 這一行後面。Perl 的 <code>system</code> 命令將會執行跟在它後面的 shell 命令，並把結果返回給程序。此時，我們將會通過 <code>free</code> 命令獲得當前的內存使用量。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>system &quot;free | grep Mem\\n&quot;;</span></span></code></pre></div><p>現在，重新運行這個程序，並把結果重定向到一個文件，在瀏覽器中重新加載這個文件。你將會看到額外的一行，它展示了系統的內存統計數據。多次運行程序並刷新瀏覽器，你將會發現，內存使用量應該是不斷變化的。</p><h3 id="使用-bash" tabindex="-1">使用 Bash <a class="header-anchor" href="#使用-bash" aria-label="Permalink to “使用 Bash”">​</a></h3><p>Bash 可能是用於 CGI 腳本中最簡單的語言。用 Bash 來進行 CGI 編程的最大優勢是它能夠直接訪問所有的標準 GNU 工具和系統程序。</p><p>把已經存在的 <code>index.cgi</code> 文件重命名為 <code>Perl.index.cgi</code>，然後創建一個新的 \`index.cgi 文件並添加下面這些內容。記得設置權限使它可執行。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#!/bin/bash</span></span>
<span class="line"><span>echo &quot;Content-type: text/html&quot;</span></span>
<span class="line"><span>echo &quot;&quot;</span></span>
<span class="line"><span>echo &#39;&lt;html&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;head&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;meta http-equiv=&quot;Content-Type&quot; content=&quot;text/html; charset=UTF-8&quot;&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;title&gt;Hello World&lt;/title&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;/head&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;body&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;h1&gt;Hello World&lt;/h1&gt;&lt;p&gt;&#39;</span></span>
<span class="line"><span>echo &#39;Using Bash&lt;p&gt;&#39;</span></span>
<span class="line"><span>free | grep Mem</span></span>
<span class="line"><span>echo &#39;&lt;/body&gt;&#39;</span></span>
<span class="line"><span>echo &#39;&lt;/html&gt;&#39;</span></span>
<span class="line"><span>exit 0</span></span></code></pre></div><p>在命令列中執行這個文件並查看輸出，然後再次運行並把結果重定向到一個臨時結果文件中。然後，刷新瀏覽器查看它所展示的網頁是什麼樣子。</p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>創建能夠生成許多種動態網頁的 CGI 程序實際上非常簡單。儘管這是一個很簡單的例子，但是現在你應該看到一些可能性了。</p><hr>`,22)),l("p",null,[s[5]||(s[5]=a("via: ",-1)),t(e,{href:"https://opensource.com/article/17/12/cgi-scripts"},{default:n(()=>[...s[4]||(s[4]=[a("https://opensource.com/article/17/12/cgi-scripts",-1)])]),_:1})]),l("p",null,[s[9]||(s[9]=a("作者：",-1)),t(e,{href:"https://opensource.com/users/dboth"},{default:n(()=>[...s[6]||(s[6]=[a("David Both",-1)])]),_:1}),s[10]||(s[10]=a(" 譯者：",-1)),t(e,{href:"https://github.com/ucasFL"},{default:n(()=>[...s[7]||(s[7]=[a("ucasFL",-1)])]),_:1}),s[11]||(s[11]=a(" 校對：",-1)),t(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[8]||(s[8]=[a("wxy",-1)])]),_:1})]),l("p",null,[s[14]||(s[14]=a("本文由 ",-1)),t(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[12]||(s[12]=[a("LCTT",-1)])]),_:1}),s[15]||(s[15]=a(" 原創編譯，",-1)),t(e,{href:"https://linux.cn/"},{default:n(()=>[...s[13]||(s[13]=[a("Linux中國",-1)])]),_:1}),s[16]||(s[16]=a(" 榮譽推出",-1))])])}const x=p(h,[["render",g]]);export{T as __pageData,x as default};
